// tongTien = "total amount", gio = "cart", apGiamGia = "apply discount", mon = "item", soLuong = "quantity"
const MENU = { "ca-phe-den": 25000, "ca-phe-sua": 29000, "tra-dao": 34500, "banh-mi": 20000 };

function tongTien(gio) {
  let tong = 0;
  for (const dong of gio) tong += MENU[dong.mon] * dong.soLuong;
  return Math.floor(tong / 1000) * 1000;
}

function apGiamGia(tong, ma) {
  if (ma === "GIAM10" && tong > 100000) return tong - tong / 10;
  return tong;
}

const kiem = [
  ["tongTien keeps its old behaviour", tongTien([{ mon: "tra-dao", soLuong: 1 }]), 34500],
  ["GIAM10 with a 200000 order", apGiamGia(200000, "GIAM10"), 180000],
  ["GIAM10 with an order of exactly 100000", apGiamGia(100000, "GIAM10"), 90000],
  ["GIAM10 with a 99000 order", apGiamGia(99000, "GIAM10"), 99000],
  ["no code", apGiamGia(200000, ""), 200000],
];
for (const [ten, that, mong] of kiem) {
  console.log(ten + ": " + (that === mong ? "pass" : "fail (got " + that + ", expected " + mong + ")"));
}

